describe('Animated Transitions Between Async Page Loads', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display loading spinner while async page loads and then fade in content', () => {
    // Intercept the API call
    cy.intercept('GET', '/api/page1').as('loadPage1');

    // Click the button to load the first page
    cy.get('[data-testid="load-page-btn"]').click();

    // Wait for the API call to complete
    cy.wait('@loadPage1');

    // Verify loading spinner is visible
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Verify spinner is animated
    cy.get('[data-testid="loading-spinner"]').should('have.class', 'spinner');

    // Verify content container is initially empty
    cy.get('[data-testid="page-content"]').should('be.empty');

    // Click the button to load the second page
    cy.get('[data-testid="load-page-btn"]').click();

    // Intercept the second API call
    cy.intercept('GET', '/api/page2').as('loadPage2');

    // Wait for the second API call to complete
    cy.wait('@loadPage2');

    // Verify loading spinner is hidden
    cy.get('[data-testid="loading-spinner"]').should('not.exist');

    // Verify content container is now visible
    cy.get('[data-testid="page-content"]').should('be.visible');

    // Verify content is loaded
    cy.get('[data-testid="page-title"]').should('contain', 'Page 2');
    cy.get('[data-testid="page-description"]').should('contain', 'Welcome to Page 2');

    // Verify animation fades in content
    cy.get('[data-testid="page-content"]').should('have.css', 'opacity', '1');
  });

  it('should handle failed async page loads with error state and retry button', () => {
    // Intercept the API call with a 500 error
    cy.intercept('GET', '/api/page3', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('loadPage3');

    // Click the button to load the third page
    cy.get('[data-testid="load-page-btn"]').click();

    // Wait for the failed API call
    cy.wait('@loadPage3');

    // Verify error state is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Failed to load page');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');

    // Click the retry button
    cy.get('[data-testid="retry-button"]').click();

    // Intercept the API call again
    cy.intercept('GET', '/api/page3').as('loadPage3Retry');

    // Wait for the retry API call
    cy.wait('@loadPage3Retry');

    // Verify error state is cleared
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify loading spinner is visible again
    cy.get('[data-testid="loading-spinner"]').should('be.visible');

    // Verify content container is empty
    cy.get('[data-testid="page-content"]').should('be.empty');

    // Verify retry button is no longer visible
    cy.get('[data-testid="retry-button"]').should('not.exist');
  });
});
